pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 duration, uint256 ts) public {
        duration = bound(duration, 1, 10_000 days - 1);
        ts = bound(ts, 2, 2_000_000_000);
        vm.warp(ts);

        // adversarial counterparties: an ERC-1271 maker whose signatures always verify,
        // and a fake base-asset token that accepts every transferFrom
        ValidSigner maker = new ValidSigner();
        TokenFaker base = new TokenFaker();

        PuttyV2.Order memory order;
        order.maker = address(maker);
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = address(base);
        order.strike = 1;
        order.premium = 1;
        order.duration = duration;
        order.expiration = ts + 1 days;
        order.nonce = 0;
        order.whitelist = new address[](0);
        order.floorTokens = new address[](0);
        order.erc20Assets = new PuttyV2.ERC20Asset[](0);
        order.erc721Assets = new PuttyV2.ERC721Asset[](0);

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory sig = new bytes(65);

        vm.prank(address(this));
        c.fillOrder(order, sig, floorAssetTokenIds);

        bytes32 longKey = c.hashOrder(order);
        assertTrue(
            c.positionExpirations(uint256(longKey)) == ts + duration,
            "stored expiration must be fill time plus duration"
        );
    }
}

contract ValidSigner {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }
}

contract TokenFaker {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
